SELECT s1.`c0` AS `id`, s1.`c1` AS `city` FROM (SELECT s2.`c5` AS `c0`, s2.`c6` AS `c1` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c2` AS `c2`, s3.`c3` AS `c3`, s3.`c4` AS `c4`, s3.`c0` AS `c5`, s3.`c4` AS `c6` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c2` AS `c2`, s5.`c0` AS `c3`, s5.`c1` AS `c4` FROM (SELECT `id` AS `c0`, `customer` AS `c1`, `amount` AS `c2` FROM `orders`) AS s4 INNER JOIN (SELECT `name` AS `c0`, `city` AS `c1` FROM `customers`) AS s5 ON (s4.`c1` = s5.`c0`)) AS s3) AS s2) AS s1
